=head3 Accessors

=over 4

=item * C<< $msg->psc_connection_id() >> / C<< $msg->psc_connection_id($value) >>

Type: C<String>

Required. The PSC connection id of the forwarding rule connected to the
service attachment.

=item * C<< $msg->address() >> / C<< $msg->address($value) >>

Type: C<String>

Required. The IP allocated on the consumer network for the PSC forwarding
rule.

=item * C<< $msg->forwarding_rule() >> / C<< $msg->forwarding_rule($value) >>

Type: C<String>

Required. The URI of the consumer side forwarding rule.
Example:
projects/{projectNumOrId}/regions/us-east1/forwardingRules/{resourceId}.

=item * C<< $msg->project_id() >> / C<< $msg->project_id($value) >>

Type: C<String>

Optional. Project ID of the consumer project where the forwarding rule is
created in.

=item * C<< $msg->network() >> / C<< $msg->network($value) >>

Type: C<String>

Required. The consumer network where the IP address resides, in the form of
projects/{project_id}/global/networks/{network_id}.

=item * C<< $msg->service_attachment() >> / C<< $msg->service_attachment($value) >>

Type: C<String>

Required. The service attachment which is the target of the PSC connection,
in the form of
projects/{project-id}/regions/{region}/serviceAttachments/{service-attachment-id}.

=item * C<< $msg->psc_connection_status() >> / C<< $msg->psc_connection_status($value) >>

Type: C<Enum> (L<Google::Cloud::Redis::Cluster::V1::PscConnectionStatus>)

Output only. The status of the PSC connection.
Please note that this value is updated periodically.
To get the latest status of a PSC connection, follow
https://cloud.google.com/vpc/docs/configure-private-service-connect-services#endpoint-details.

=item * C<< $msg->connection_type() >> / C<< $msg->connection_type($value) >>

Type: C<Enum> (L<Google::Cloud::Redis::Cluster::V1::ConnectionType>)

Output only. Type of the PSC connection.

=back

